#include <iostream>
#include <cstddef>

struct Example {
    char c;
    int i;
};

struct Card {
    const char* face;
    const char* suit;
};

int main() {
    // Demonstrate padding:
    // sizeof(char) is 1, sizeof(int) is 4, but sizeof(Example) is typically 8 due to 3 padding bytes.
    std::cout << "sizeof(Example): " << sizeof(Example) << "\n";
    std::cout << "offset of i: " << offsetof(Example, i) << "\n";

    // Initializer list with fewer values sets remaining to nullptr/0
    Card c1{"Three", "Hearts"};
    Card c2{"Ace"}; // suit is implicitly nullptr

    std::cout << "Card 1: " << c1.face << " of " << c1.suit << "\n";
    std::cout << "Card 2 face: " << c2.face << ", suit is null: " << (c2.suit == nullptr ? "yes" : "no") << "\n";
    return 0;
}

#include <iostream>

struct Card {
    const char* face;
    const char* suit;
};

int main() {
    Card aCard;
    aCard.face = "Ace";
    aCard.suit = "Spades";

    Card* cardPtr = &aCard;

    // Three equivalent ways to access members
    std::cout << aCard.face << " of " << aCard.suit << "\n";
    std::cout << cardPtr->face << " of " << cardPtr->suit << "\n";
    std::cout << (*cardPtr).face << " of " << (*cardPtr).suit << "\n";

    return 0;
}

#include <iostream>

// Defining struct with typedef alias style
typedef struct CardTag {
    const char* face;
    const char* suit;
} Card;

// Pass by value (copies structure, caller unaffected)
void printByValue(Card c) {
    std::cout << "By value: " << c.face << " of " << c.suit << "\n";
}

// Pass by pointer (efficient, can modify caller if not const)
void setFace(Card* const cPtr, const char* newFace) {
    if (cPtr) {
        cPtr->face = newFace;
    }
}

int main() {
    Card card{"King", "Diamonds"};
    printByValue(card);

    setFace(&card, "Queen");
    std::cout << "After modification: " << card.face << " of " << card.suit << "\n";
    return 0;
}
